input.command:
cat > config.json << 'EOF'
{
  "name": "GraphQL Migration RFC",
  "description": "Technical RFC proposing backend switch from REST to GraphQL for client-facing APIs, covering pain points, approach, projects/tasks schema sketch, and open questions."
}
EOF

cat > topology.json << 'EOF'
{
  "agents": {
    "rfc_writer": { "depends_on": [] }
  }
}
EOF

cat > config.json << 'EOF'
{
  "name": "GraphQL RFC API Design Review",
  "description": "API design review of GraphQL migration RFC evaluating schema complexity, query limits, pagination, errors, and REST compatibility with structured verdicts and overall recommendation."
}
EOF

cat > topology.json << 'EOF'
{
  "agents": {
    "reviewer": { "depends_on": [] }
  }
}
EOF

cat > config.json << 'EOF'
{
  "name": "GraphQL Performance Review",
  "description": "Performance review of GraphQL migration RFC, analyzing N+1 query risks, payload sizes vs REST, caching strategies, latency impacts with quantified estimates, per-area verdicts, and overall recommendation."
}
EOF

cat > topology.json << 'EOF'
{
  "agents": {
    "reviewer": { "depends_on": [] }
  }
}
EOF

cat > config.json << 'EOF'
{
  "name": "GraphQL Security Review",
  "description": "Security review of GraphQL RFC evaluating query complexity limits, authorization model, introspection, rate limiting, custom scalars risks, with per-area verdicts and overall recommendation."
}
EOF

cat > topology.json << 'EOF'
{
  "agents": {
    "reviewer": { "depends_on": [] }
  }
}
EOF

cat > config.json << 'EOF'
{
  "name": "DX Review of GraphQL RFC",
  "description": "Reviews the GraphQL migration RFC from frontend developer experience: client codegen, type safety, docs tooling, testing strategy, migration burden; with per-area verdicts and overall recommendation."
}
EOF

cat > topology.json << 'EOF'
{
  "agents": {
    "dx_reviewer": { "depends_on": [] }
  }
}
EOF

cat > config.json << 'EOF'
{
  "name": "Review Synthesis",
  "description": "Synthesizes API, Performance, and Security reviews of GraphQL RFC into a conflict resolution document featuring a table of verdicts per area, proposed resolutions for disagreements, consensus summaries, and prioritized action items."
}
EOF

cat > topology.json << 'EOF'
{
  "agents": {
    "synthesizer": { "depends_on": [] }
  }
}
EOF

cat > config.json << 'EOF'
{
  "name": "GraphQL Migration Plan",
  "description": "Phased migration plan from REST to GraphQL based on DX review, detailing deliverables, responsibilities, rollback triggers, and success metrics per phase in a structured timeline."
}
EOF

cat > topology.json << 'EOF'
{
  "agents": {
    "planner": { "depends_on": [] }
  }
}
EOF

cat > config.json << 'EOF'
{
  "name": "Architecture Decision Record",
  "description": "Formal ADR for GraphQL adoption synthesizing review consensus and migration plan, structured with Title, Status, Context, Decision, Consequences, Compliance, and Migration References cross-linking to conflict table and timeline."
}
EOF

cat > topology.json << 'EOF'
{
  "agents": {
    "adr_writer": { "depends_on": [] }
  }
}
EOF
